            );
            assert!(
                re.is_match(&format!("SRC/FILE.{}", ext.to_uppercase())),
                "pattern is not case-insensitive for '{ext}'"
            );
        }
        assert!(!re.is_match("src/file.txt"));
        assert!(!re.is_match("src/file.rss"));
    }

